-- ===== 20250701000000_billing_and_usage.sql =====
-- Billing + usage metering. All writes come from Edge Functions using the service role.

create table if not exists public.subscriptions (
  user_id uuid primary key references auth.users(id) on delete cascade,
  stripe_customer_id text unique,
  stripe_subscription_id text unique,
  status text not null default 'none',        -- active | trialing | past_due | canceled | none ...
  price_id text,
  current_period_end timestamptz,
  cancel_at_period_end boolean not null default false,
  updated_at timestamptz not null default now()
);
alter table public.subscriptions enable row level security;
drop policy if exists "Users can read their own subscription" on public.subscriptions;
create policy "Users can read their own subscription"
  on public.subscriptions for select using (auth.uid() = user_id);
-- No insert/update/delete policies: clients can never grant themselves a plan.

create table if not exists public.ai_usage_daily (
  user_id uuid not null references auth.users(id) on delete cascade,
  day date not null default (now() at time zone 'utc')::date,
  count integer not null default 0,
  primary key (user_id, day)
);
alter table public.ai_usage_daily enable row level security;
drop policy if exists "Users can read their own usage" on public.ai_usage_daily;
create policy "Users can read their own usage"
  on public.ai_usage_daily for select using (auth.uid() = user_id);

-- Atomically add one use and return the new count for today (service role only).
create or replace function public.increment_ai_usage(p_user uuid)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare new_count integer;
begin
  insert into public.ai_usage_daily (user_id, day, count)
  values (p_user, (now() at time zone 'utc')::date, 1)
  on conflict (user_id, day) do update set count = public.ai_usage_daily.count + 1
  returning count into new_count;
  return new_count;
end;
$$;
revoke all on function public.increment_ai_usage(uuid) from public, anon, authenticated;
grant execute on function public.increment_ai_usage(uuid) to service_role;

-- Stripe webhooks can be delivered more than once; remember which events we handled.
create table if not exists public.stripe_events (
  id text primary key,
  type text not null,
  received_at timestamptz not null default now()
);
alter table public.stripe_events enable row level security;  -- no policies: service role only


-- ===== 20250701000100_voice_stories.sql =====
-- Storage + table used by the voice-story-generator function.
insert into storage.buckets (id, name, public)
values ('voice-stories', 'voice-stories', false)
on conflict (id) do update set public = false;

create table if not exists public.voice_stories (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  story_text text not null,
  audio_path text,
  duration integer,
  word_count integer,
  voice_name text,
  language text,
  style text,
  tone text,
  audio_format text,
  audio_quality text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists voice_stories_user_idx on public.voice_stories (user_id, created_at desc);
alter table public.voice_stories enable row level security;
drop policy if exists "Users read their own stories" on public.voice_stories;
create policy "Users read their own stories" on public.voice_stories for select using (auth.uid() = user_id);
drop policy if exists "Users delete their own stories" on public.voice_stories;
create policy "Users delete their own stories" on public.voice_stories for delete using (auth.uid() = user_id);

-- Owners may read their own audio files (folder name = user id); only the service role writes.
drop policy if exists "Users read their own voice files" on storage.objects;
create policy "Users read their own voice files" on storage.objects for select
  using (bucket_id = 'voice-stories' and (storage.foldername(name))[1] = auth.uid()::text);


